package com.careerpilot.modules.assessment.generation;
import org.springframework.stereotype.Component;import java.util.*;
@Component
public class GeneratedQuestionValidator{
 public List<GeneratedQuestion>validate(List<GeneratedQuestion>questions,Set<String>allowedSkills,int maximum){if(questions==null||questions.isEmpty()||questions.size()>maximum)throw new IllegalArgumentException("Invalid generated question count");Set<String>texts=new HashSet<>();List<GeneratedQuestion>valid=new ArrayList<>();for(var q:questions){String text=clean(q.questionText());if(text.isBlank()||text.length()>1000||q.difficulty()==null||q.explanation()==null||clean(q.explanation()).isBlank()||q.explanation().length()>1500)throw new IllegalArgumentException("Invalid generated question");if(!texts.add(normalize(text)))throw new IllegalArgumentException("Duplicate generated question");String skill=clean(q.skillTag());if(skill.isBlank()||allowedSkills.stream().noneMatch(v->normalize(v).equals(normalize(skill))))throw new IllegalArgumentException("Generated skill is outside requested skills");if(q.options()==null||q.options().size()!=4)throw new IllegalArgumentException("MCQ must have exactly four options");Set<String>keys=new HashSet<>(),optionTexts=new HashSet<>();int correct=0;List<GeneratedQuestion.GeneratedOption>options=new ArrayList<>();for(var o:q.options()){String key=clean(o.key()).toUpperCase(Locale.ROOT),option=clean(o.text());if(!keys.add(key)||!optionTexts.add(normalize(option))||!Set.of("A","B","C","D").contains(key)||option.isBlank()||option.length()>500)throw new IllegalArgumentException("Invalid or duplicate generated option");if(o.correct())correct++;options.add(new GeneratedQuestion.GeneratedOption(key,option,o.correct()));}if(correct!=1)throw new IllegalArgumentException("MCQ must contain exactly one correct option");valid.add(new GeneratedQuestion(text,q.difficulty(),skill,clean(q.explanation()),List.copyOf(options)));}return List.copyOf(valid);}
 private String clean(String value){return value==null?"":value.strip().replaceAll("\\s+"," ");}private String normalize(String value){return clean(value).toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+"," ").strip();}
}
